package com.brainserve.onboarding.contracts.infrastructure.persistence;
import com.brainserve.onboarding.contracts.domain.model.*;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ContractRepository extends JpaRepository<Contract,UUID>{Optional<Contract> findByOrganizationIdAndId(UUID org,UUID id);Optional<Contract> findByOrganizationIdAndCreationIdempotencyKey(UUID org,String key);Optional<Contract> findByProviderAndProviderDocumentId(String provider,String providerDocumentId);Page<Contract> findAllByOrganizationId(UUID org,Pageable pageable);Page<Contract> findAllByOrganizationIdAndProjectId(UUID org,UUID projectId,Pageable pageable);Page<Contract> findAllByOrganizationIdAndProjectIdAndStatusIn(UUID org,UUID projectId,Collection<ContractStatus> statuses,Pageable pageable);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from Contract c where c.organizationId=:org and c.id=:id")Optional<Contract> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);}
